SELECT     soh.LOC                                                                    AS \"Store Number\",     st.STORE_NAME                                                              AS \"Store Name\",     soh.ITEM,     im.ITEM_DESC                                                               AS \"Item Description\",     im.DEPT,     d.DEPT_NAME                                                                AS \"Department Name\",     im.CLASS,     im.SUBCLASS,     soh.STOCK_ON_HAND  as \"Stock On Hand\",     soh.QTY_SOLD as \"Quantity Sold\",     soh.QTY_RECEIVED as \"Quantity Recieved\",     ROUND(soh.QTY_SOLD / NULLIF(soh.QTY_RECEIVED, 0) * 100, 2) as \"Sell Through Percentage\",     soh.LAST_SOLD as \"Last Sold Date\" FROM rds_wv_item_loc_soh soh INNER JOIN rds_wv_item_master im ON soh.ITEM = im.ITEM LEFT JOIN rds_wv_deps d ON im.DEPT = d.DEPT LEFT JOIN rds_wv_store st ON soh.LOC = st.STORE WHERE soh.LOC_TYPE = 'S' AND soh.QTY_RECEIVED &gt; 0</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Store Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Store Name</ds:name><ds:datatype>varchar(150)</ds:datatype></ds:column><ds:column><ds:name>ITEM</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Item Description</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPT</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Department Name</ds:name><ds:datatype>varchar(120)</ds:datatype></ds:column><ds:column><ds:name>CLASS</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUBCLASS</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Stock On Hand</ds:name><ds:da